// ─── Configuración ────────────────────────────────────────────────────────
// Rellena estos valores, o defínelos como variables de entorno de n8n. Ojo: por
// defecto n8n bloquea $env dentro de los nodos Code
// (N8N_BLOCK_ENV_ACCESS_IN_NODE); si no la desactivas, se usan los de aquí.
//
// IG_USER_ID es el id de tu cuenta de Instagram Business/Creator, no el @usuario:
//   GET /{page-id}?fields=instagram_business_account
const AJUSTES = {
  IG_USER_ID: 'PON_AQUI_TU_IG_USER_ID',
  GRAPH_API_VERSION: 'v25.0',
  GRAPH_API_HOST: 'https://graph.facebook.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const IG_USER_ID = env.IG_USER_ID || AJUSTES.IG_USER_ID;
const VERSION = env.GRAPH_API_VERSION || AJUSTES.GRAPH_API_VERSION;
const HOST = env.GRAPH_API_HOST || AJUSTES.GRAPH_API_HOST;

if (IG_USER_ID === 'PON_AQUI_TU_IG_USER_ID') {
  throw new Error('Falta IG_USER_ID: rellénalo en el nodo Configuración o define la variable de entorno.');
}

// El panel pinta una cuadrícula 3×3; se piden 9 piezas.
const LIMIT = Number($input.first().json.query?.limit ?? 9);

return [{ json: { igUserId: IG_USER_ID, version: VERSION, host: HOST, limit: LIMIT } }];

// media_url caduca en Instagram, pero sirve para pintar el feed al momento.
// Para algo permanente, descarga la imagen y guárdala tú.
const res = $('Publicaciones').first().json ?? {};

if (res.error) return [{ json: { source: 'instagram', error: res.error.message, slots: [] } }];

const FORMAT = { VIDEO: 'reel', CAROUSEL_ALBUM: 'carousel', IMAGE: null };

const slots = (res.data ?? []).map((m) => ({
  id: m.id,
  image: m.media_type === 'VIDEO' ? (m.thumbnail_url ?? m.media_url) : m.media_url,
  alt: (m.caption ?? 'Publicación de Instagram').slice(0, 80),
  title: (m.caption ?? '').split('\n')[0].slice(0, 90) || 'Sin título',
  format: FORMAT[m.media_type] ?? null,
  permalink: m.permalink,
  timestamp: m.timestamp,
  stats: [`♥ ${m.like_count ?? 0}`, `💬 ${m.comments_count ?? 0}`],
}));

return [{ json: { source: 'instagram', slots } }];
